def clean_ocr_amount(text):
    """Clean common OCR errors in amounts."""
    replacements = {
        'O': '0', 'o': '0', 'I': '1', 'l': '1', 'i': '1',
        'S': '5', 's': '5', 'B': '8', 'U': '0'
    }
    result = text
    for old, new in replacements.items():
        result = result.replace(old, new)
    return result

def extract_total_amount_debug(text, filename):
    """Extract total amount with debugging."""
    lines = text.split('\n')

    exclusion_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST',
        'DISCOUNT', 'CHANGE', 'CASH TENDERED', 'CASH PAYMENT',
        'PAYMENT', 'TENDERED'
    ]

    priority_keywords = [
        ['GRAND TOTAL'],
        ['TOTAL RM', 'TOTAL: RM', 'TOTAL :RM'],
        ['TOTAL AMOUNT'],
        ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
    ]

    amount_pattern = r'(?:RM\s*)?(\d{1,3}(?:[,\s]\d{3})*\.\d{2}|\d+\.\d{2})'
    flexible_amount_pattern = r'(?:RM\s*)?([0-9OolIiSsBU]{1,3}(?:[,\s]?[0-9OolIiSsBU]{3})*\.?[0-9OolIiSsBU]{2}|[0-9OolIiSsBU]+\.?[0-9OolIiSsBU]{2})'

    for keyword_group in priority_keywords:
        for i, line in enumerate(lines):
            line_upper = line.upper()

            if any(excl in line_upper for excl in exclusion_keywords):
                continue

            if any(keyword in line_upper for keyword in keyword_group):
                print(f"{filename}: Found keyword in line: {line[:60]}")

                # Try strict pattern
                match = re.search(amount_pattern, line, re.IGNORECASE)
                if match:
                    return match.group(1).replace(',', '').replace(' ', '')

                # Try flexible pattern
                match = re.search(flexible_amount_pattern, line, re.IGNORECASE)
                if match:
                    cleaned = clean_ocr_amount(match.group(1)).replace(',', '').replace(' ', '')
                    return cleaned

                # Try next line
                if i + 1 < len(lines):
                    next_line = lines[i + 1]
                    match = re.search(amount_pattern, next_line, re.IGNORECASE)
                    if match:
                        return match.group(1).replace(',', '').replace(' ', '')

    return None

